% make_results_VR_girolami.m
%
% Computes variance reduction factors for the log-Gaussian Cox process experiment
% and writes the LaTeX table for:
%
%   Table 8  (Section 5.2)  -- log-Gaussian Cox process (d=4096), n in {1000, 10000}
%
% Reads:
%   results/Cox_regression/logGaussianCoxGirolami_Marg_repeat<r>_Marg_fixedhypers_VR_<T>.mat
%   Each file contains: means (1 x d), means_cv (1 x d)
%   Generated by demLogGaussianCoxGirolamiMarg_gimala_VR(rep, T).
%
% To reproduce both n columns, run run_VR_experiments.m first (100 reps,
% T in {1000, 10000}).  If only some T values are available, this script
% writes '--' for any missing T.
%
% Output (written to diagrams/):
%   VR_GaussianCox_table8.txt   LaTeX row for Table 8
%
% Run from the repository root.

outdir   = 'diagrams/';
resdir   = 'results/Cox_regression/';
dataName = 'logGaussianCoxGirolami_Marg';

Repeats = 100;
T_list  = [1000, 10000];

ratio_min = NaN(1, length(T_list));
ratio_max = NaN(1, length(T_list));

for ti = 1:length(T_list)
    T = T_list(ti);
    means_all    = [];
    means_cv_all = [];

    for r = 1:Repeats
        fname = [resdir dataName '_repeat' num2str(r) ...
                 '_Marg_fixedhypers_VR_' num2str(T) '.mat'];
        if exist(fname, 'file')
            tmp = load(fname, 'means', 'means_cv');
            means_all    = [means_all;    tmp.means];
            means_cv_all = [means_cv_all; tmp.means_cv];
        end
    end

    if size(means_all, 1) >= 2
        var_plain = var(means_all,    [], 1);
        var_vr    = var(means_cv_all, [], 1);
        ratio = var_plain ./ max(var_vr, 1e-12);
        ratio_min(ti) = min(ratio);
        ratio_max(ti) = max(ratio);
    end
end

fid = fopen([outdir 'Table8.txt'], 'w');
fprintf(fid, 'Cox process ($d=4096$)');
for ti = 1:length(T_list)
    if ~isnan(ratio_min(ti))
        fprintf(fid, ' & %.2f-%.2f', ratio_min(ti), ratio_max(ti));
    else
        fprintf(fid, ' & --');
    end
end
fprintf(fid, ' \\\\\n');
fclose(fid);
fprintf('Written: %sTable8.txt  (Table 8, Section 5.2)\n', outdir);
